inline constexpr std::string_view Hello_DEFAULT_DEVICE    = "dev01";
inline constexpr std::string_view Hello_DEFAULT_WORKSPACE = "demo";
inline constexpr std::string_view Hello_DEFAULT_MODULE    = "pubber";
